"""Builds the second-round paragraphs of the withdrawal note from the result files, so no number is typed by hand.
Prints Markdown, then LaTeX. Usage: python make_note_blocks.py"""
import json, os
H = os.path.dirname(os.path.abspath(__file__)); J = lambda n: json.load(open(os.path.join(H, "results", n)))
a = J("pr3_omp_oracles_dual.json"); lt = J("pr3_lasso.json"); f = J("pr4_sae_features.json")
S = a["solvers"]; c = a["support_composition_typical"]; at = a["attention_oracle"]; em = a["embedding_oracle"]; sa = at["selected_attention_atoms"]; T = f["targets"]
r = lambda k: f"{k['recall_top1']['point']:.3f}"; fv = lambda k: f"{k['fvu_refit_typical']:.3f}"; pc = lambda x, d=0: f"{100 * x:.{d}f}"
rows = [("OMP", S["omp"]), ("one-shot ranking", S["oneshot"]), ("one-shot ranking through the dual frame", S["dual_frame_eps0.01"]), ("LASSO", lt["solvers"]["lasso"])]
u = lambda t, d="weight": T[t][d]["unexplained_median"]["16"]; m1 = lambda t: T[t]["weight"]["first_atom"]["mlp"]
nonmlp = c["attention"] + c["token"] + c["position"] + c["bias"]
V = dict(sign=pc(sa["sign_agreement"]), ratio=f"{sa['median_ratio_real']:.1f}", cur=pc(em["selected_token_rows"]["current_token"], 1), ownpos=pc(em["selected_position_rows_that_are_own"], 1), dom=pc(at["raw"]["dominant_head_selected"]), domc=pc(at["centred"]["dominant_head_selected"]),
         rnd=pc(at["random_head_selected"]), own=pc(em["own_token_row_in_support"]), nonmlp=pc(nonmlp), mlp=pc(c["mlp"]), att=pc(c["attention"]), tok=pc(c["token"]), pos=pc(c["position"], 1),
         nf=f"{f['n_features']:,}", fm=pc(m1("sae_features")), rm=pc(m1("random_directions")), fu=f"{u('sae_features'):.2f}", fr=f"{u('sae_features', 'rotated'):.2f}", su=f"{u('typical_states'):.2f}")
md_solver = ("What pursuit adds is reconstruction, and it costs identification. With 64 atoms each on the same states:\n\n| solver | largest write identified | FVU of a refit on its atoms |\n|---|---|---|\n"
             + "".join(f"| {n} | {r(k)} | {fv(k)} |\n" for n, k in rows) + "\nOMP reconstructs best and identifies worst. So the paper's 65% is OMP's limit, not the dictionary's.")
md_sae = ("**Reviewers MgDZ and 7MWE: SAE features, as vectors no prompt produced.** I decomposed all {nf} decoder directions of the residual SAE of Bloom (2024) for this layer over the same dictionary. The first atom chosen is an MLP row for {fm}% of features, against {rm}% for random directions. "
          "Sixteen atoms leave {fu} of a feature unexplained, against {fr} under the rotated dictionary and {su} for a typical state. So in this dictionary a feature looks like a state, not like a single write, and its nearest write is usually an MLP neuron. Whether the recovered writes are as interpretable as the features is still untested.").format(**V)
md_oracle = ("**Reviewer NMa5: ground truth for the attention and embedding atoms.** I built the oracle you describe. Each head's true write, projected on that head's own basis atoms, gives a true coefficient for every attention atom. For the embeddings, the only true writes are the token's own row and its own position row. On typical states, with the 64-atom OMP support:\n\n"
             "| part of the support | share | against ground truth |\n|---|---|---|\n| MLP rows | {mlp}% | 35% are real writes (Section 4.2) |\n| attention atoms | {att}% | sign right for {sign}%, against 50% by chance |\n| token-embedding rows | {tok}% | {cur}% are the current token |\n| position rows | {pos}% | {ownpos}% are the current position |\n\n"
             "The head that wrote the most has an atom in the support for {dom}% of tokens, or {domc}% with centred writes, against {rnd}% for a random head. The token's own embedding row is selected for {own}% of tokens. So the non-MLP atoms, {nonmlp}% of the support, should not be read as attributions.").format(**V)
tex_solver = ("What pursuit adds is reconstruction, and it costs identification. With 64 atoms each on the same states:\n\n{\\centering\\small\n\\begin{tabular}{lcc}\n\\toprule\nsolver & largest write identified & FVU of a refit on its atoms \\\\\n\\midrule\n"
              + "".join(f"{n} & {r(k)} & {fv(k)} \\\\\n" for n, k in rows) + "\\bottomrule\n\\end{tabular}\\par}\n\nOMP reconstructs best and identifies worst. So the paper's 65\\% is OMP's limit, not the dictionary's.")
tex_sae = md_sae.replace("**Reviewers MgDZ and 7MWE: SAE features, as vectors no prompt produced.**", "\\textbf{Reviewers MgDZ and 7MWE: SAE features, as vectors no prompt produced.}").replace("%", "\\%")
tex_oracle = ("\\textbf{{Reviewer NMa5: ground truth for the attention and embedding atoms.}} I built the oracle you describe. Each head's true write, projected on that head's own basis atoms, gives a true coefficient for every attention atom. For the embeddings, the only true writes are the token's own row and its own position row. On typical states, with the 64-atom OMP support:\n\n"
              "{{\\centering\\small\n\\begin{{tabular}}{{lcl}}\n\\toprule\npart of the support & share & against ground truth \\\\\n\\midrule\nMLP rows & {mlp}\\% & 35\\% are real writes (Section~4.2) \\\\\nattention atoms & {att}\\% & sign right for {sign}\\%, against 50\\% by chance \\\\\ntoken-embedding rows & {tok}\\% & {cur}\\% are the current token \\\\\nposition rows & {pos}\\% & {ownpos}\\% are the current position \\\\\n\\bottomrule\n\\end{{tabular}}\\par}}\n\n"
              "The head that wrote the most has an atom in the support for {dom}\\% of tokens, or {domc}\\% with centred writes, against {rnd}\\% for a random head. The token's own embedding row is selected for {own}\\% of tokens. So the non-MLP atoms, {nonmlp}\\% of the support, should not be read as attributions.").format(**V)
json.dump(dict(md_solver=md_solver, md_sae=md_sae, md_oracle=md_oracle, tex_solver=tex_solver, tex_sae=tex_sae, tex_oracle=tex_oracle), open(os.path.join(H, "results", "note_blocks.json"), "w"), indent=1)
print(md_solver, "\n\n", md_sae, "\n\n", md_oracle)
